module multi_pipe_4bit(clk,rst_n,mul_a,mul_b,mul_out);
//Do not modify the module name
parameter size = 4;
//------Input Ports------
//Multiplicand
input wire [size-1:0] mul_a;
//Multiplier
input wire [size-1:0] mul_b;
//Clock Signal
input wire clk;
//Reset Signal
input wire rst_n;
//------Output Ports------
//Product Output
output reg [(2*size)-1:0] mul_out;
/*Write your design here*/
reg [((2*size)+1):0] mul_reg[0:4];
integer i;
wire [((2*size)):0] add_in;
//Stage 1 registers
reg [((2*size)):0] sum_tmp1,sum_tmp2;
assign add_in = mul_reg[2] + mul_reg[3];
always@(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
		for(i = 0;i<(2*size+2);i=i+1) begin
			mul_reg[i] <= 0;
		end
    end

    else begin
	    mul_reg[0] <= {{size{1'b0}},mul_a};
	    mul_reg[1] <= {{size{1'b0}},mul_b};

	    mul_reg[2] <= (mul_reg[1][0])?mul_reg[0]:('d0);
	    mul_reg[3] <= ((mul_reg[1][1])?(mul_reg[0]<<1):('d0));
	    mul_reg[4] <= ((mul_reg[1][2])?(mul_reg[0]<<2):('d0)) + ((mul_reg[1][3])?(mul_reg[0]<<3):('d0));

		sum_tmp1 <= (mul_reg[0] + (mul_reg[1][1]?mul_reg[0]<<1:'d0));
		sum_tmp2 <= (mul_reg[2] + (mul_reg[1][3]?mul_reg[0]<<3:'d0));

	    mul_reg[2] <= sum_tmp1;
	    mul_reg[3] <= sum_tmp2;

	    mul_out <= add_in;
    end
end
endmodule
